const placementSeeds = `-- name: PlacementSeeds :many

SELECT s.id, s.workspace_id, s.email, s.provider, s.auth, s.imap_host, s.imap_port, s.username, s.credentials_enc, s.status, s.status_at, s.status_detail, s.folders, s.checked_at, s.last_used_at, s.last_test_id, s.last_test_label, s.added_by, s.added_at, coalesce(u.name, '')::text AS added_by_name
FROM placement_seeds s
LEFT JOIN users u ON u.id = s.added_by
WHERE s.workspace_id = $1
ORDER BY s.added_at, s.id
`

type PlacementSeedsRow struct {
	PlacementSeed PlacementSeed `json:"placementSeed"`
	AddedByName   string        `json:"addedByName"`
}

// Placement tests (internal/placement): seed mailboxes, tests, copies.
func (q *Queries) PlacementSeeds(ctx context.Context, workspaceID uuid.UUID) ([]PlacementSeedsRow, error) {
	rows, err := q.db.Query(ctx, placementSeeds, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PlacementSeedsRow{}
	for rows.Next() {
		var i PlacementSeedsRow
		if err := rows.Scan(
			&i.PlacementSeed.ID,
			&i.PlacementSeed.WorkspaceID,
			&i.PlacementSeed.Email,
			&i.PlacementSeed.Provider,
			&i.PlacementSeed.Auth,
			&i.PlacementSeed.ImapHost,
			&i.PlacementSeed.ImapPort,
			&i.PlacementSeed.Username,
			&i.PlacementSeed.CredentialsEnc,
			&i.PlacementSeed.Status,
			&i.PlacementSeed.StatusAt,
			&i.PlacementSeed.StatusDetail,
			&i.PlacementSeed.Folders,
			&i.PlacementSeed.CheckedAt,
			&i.PlacementSeed.LastUsedAt,
			&i.PlacementSeed.LastTestID,
			&i.PlacementSeed.LastTestLabel,
			&i.PlacementSeed.AddedBy,
			&i.PlacementSeed.AddedAt,
			&i.AddedByName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

